import { Component } from '@angular/core';

@Component({
  selector: 'app-shop',
  templateUrl: './shop.component.html',
  styleUrls: ['./shop.component.scss']
})
export class ShopComponent {
  title = 'فروشگاه';
}
<section class="bg-warm min-h-screen py-12">
  <div class="container mx-auto px-4">
    <h1 class="text-3xl font-bold text-secondary mb-8">فروشگاه</h1>
    <p class="text-gray-600">محصولات به زودی اضافه می‌شوند.</p>
  </div>
</section>
